/// <summary>
/// designed from AVA
/// </summary>
class AVASFCFeedbackPost
{
    AVANdxSFCId     callerNDXSfcId;



}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_args">_args</param>
public static void main(Args    _args)
{
    AVASFCFeedbackPost      sfcFeedbackPost = new AVASFCFeedbackPost();
    sfcFeedbackPost.run();
}

/// <summary>
/// designed from AVA
/// </summary>
public void run()
{
    AVASFCFeedback      sfcFeedback;

    while select sfcFeedback
        group by NdxSFCId
            where (sfcFeedback.NdxSFCId == callerNDXSfcId || callerNDXSfcId == '')
    {
        this.importJmgRegTransClockIn(sfcFeedback.NdxSFCId);
        this.postWorkerJob(sfcFeedback.NdxSFCId);
        this.importJmgRegTransClockOut(sfcFeedback.NdxSFCId);
        this.setNDXSfcIdPosted(sfcFeedback.NdxSFCId);
    }
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_callerNDXSfcId">_callerNDXSfcId</param>
/// <returns>AVANdxSFCId</returns>
public AVANdxSFCId      parmCallerNdxSfcId(AVANdxSFCId      _callerNDXSfcId = callerNDXSfcId)
{
    callerNDXSfcId  = _callerNDXSfcId;
    return callerNDXSfcId;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_callerNdxSfcId">_callerNdxSfcId</param>
public static void processFromCallerSFC(AVANdxSFCId      _callerNdxSfcId)
{
    AVASFCFeedbackPost      sfcFeedbackPost = new AVASFCFeedbackPost();
    sfcFeedbackPost.parmCallerNdxSfcId(_callerNdxSfcId);
    sfcFeedbackPost.run();
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_curNdxSfcId">_curNdxSfcId</param>
protected void importJmgRegTransClockIn(AVANdxSFCId     _curNdxSfcId)
{
    AVASFCFeedback              sfcFeedbackClockIn;
    JmgTermReg                  jmgtermRegClockIn;

    select firstonly sfcFeedbackClockIn
    where sfcFeedbackClockIn.NdxSFCId       == _curNdxSfcId
    &&    sfcFeedbackClockIn.Posted         == NoYes::No
    &&    sfcFeedbackClockIn.JmgTermRegType == JmgTermRegType::ClockIn
    &&    sfcFeedbackClockIn.Deactivated    == NoYes::No;
    // Einstempeln
    jmgTermRegClockIn.clear();
    jmgTermRegClockIn.JobId        = sfcFeedbackClockIn.JmgJobId;
    jmgTermRegClockIn.ResNo        = sfcFeedbackClockIn.WrkCtrId;
    jmgTermRegClockIn.ProfileDate  = sfcFeedbackClockIn.JmgDate;
    jmgTermRegClockIn.Worker       = sfcFeedbackClockIn.Worker;
    jmgTermRegClockIn.RegType      = sfcFeedbackClockIn.JmgTermRegType;
    jmgTermRegClockIn.JobIdAbs     = sfcFeedbackClockIn.JmgJobId;
    jmgTermRegClockIn.RegDateTime  = sfcFeedbackClockIn.JmgDateTime;
    //jmgTermRegClockIn.JobPilote    = kcs_SFCFeedbackClockIn.KCS_JobPilote;
    jmgTermRegClockIn.StartItems   = sfcFeedbackClockIn.ProdQtyStUp;
    jmgTermRegClockIn.CostCategory = sfcFeedbackClockIn.CostCategory;
    jmgTermRegClockIn.AVANDXSfcId  = sfcFeedbackClockIn.NdxSFCId;
    jmgTermRegClockIn.AVASFCFeedbackRefRecId = sfcFeedbackClockIn.RecId;
    jmgTermRegClockIn.insert();

}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_curNdxSfcId">_curNdxSfcId</param>
protected void importJmgRegTransClockOut(AVANdxSFCId     _curNdxSfcId)
{
    AVASFCFeedback              sfcFeedbackClockOut;
    JmgTermReg                  jmgtermRegClockOut;

    select firstonly sfcFeedbackClockOut
    where sfcFeedbackClockOut.NdxSFCId       == _curNdxSfcId
    &&    sfcFeedbackClockOut.Posted         == NoYes::No
    &&    sfcFeedbackClockOut.JmgTermRegType == JmgTermRegType::ClockOut
    &&    sfcFeedbackClockOut.Deactivated    == NoYes::No;

    // Ausstempeln
    jmgtermRegClockOut.clear();
    jmgtermRegClockOut.JobId        = sfcFeedbackClockOut.JmgJobId;
    jmgtermRegClockOut.ResNo        = sfcFeedbackClockOut.WrkCtrId;
    jmgtermRegClockOut.ProfileDate  = sfcFeedbackClockOut.JmgDate;
    jmgtermRegClockOut.Worker       = sfcFeedbackClockOut.Worker;
    jmgtermRegClockOut.RegType      = sfcFeedbackClockOut.JmgTermRegType;
    jmgtermRegClockOut.JobIdAbs     = sfcFeedbackClockOut.JmgJobId;
    jmgtermRegClockOut.RegDateTime  = sfcFeedbackClockOut.JmgDateTime;
    //jmgTermRegClockIn.JobPilote    = kcs_SFCFeedbackClockIn.KCS_JobPilote;
    jmgtermRegClockOut.StartItems   = sfcFeedbackClockOut.ProdQtyStUp;
    jmgtermRegClockOut.CostCategory = sfcFeedbackClockOut.CostCategory;
    jmgtermRegClockOut.AVANDXSfcId  = sfcFeedbackClockOut.NdxSFCId;
    jmgtermRegClockOut.AVASFCFeedbackRefRecId = sfcFeedbackClockOut.RecId;
    jmgtermRegClockOut.insert();
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_ndxSFCId">_ndxSFCId</param>
protected void setNDXSfcIdPosted(AVANdxSFCId     _ndxSFCId)
{
    AVASFCFeedback      sfcFeedback;

    while select forupdate sfcFeedback
        where sfcFeedback.NDXSFCId == _ndxSfCId
        && sfcFeedback.Deactivated == NoYes::No
    {
        sfcFeedback.Posted = NoYes::Yes;
        ttsbegin;
        sfcFeedback.update();
        ttscommit;

    }
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_curNdxSFCId">_curNdxSFCId</param>
protected void postWorkerJob(AVANdxSFCId    _curNdxSFCId)
{
    AVASFCFeedback              sfcFeedbackStart;
    AVASFCFeedback              sfcFeedbackStop;
    JmgTermReg                  jmgTermRegJobStart;
    JmgTermReg                  jmgTermRegJobStop;
    JmgTmpErrorSpecification    jmgTmpErrorSpecification;
    boolean                     isWorkerJobCreated;

    RefRecId                    jmgTermRegStartRecId;
    RefRecId                    jmgTermRegEndRecId;
    JmgStampJournalTrans        jmgStampJournalTrans;

    JmgPostStandardSystem       jmgPostStandardSystem;
    //JmgProdMultiStartUp         jmgProdMultiStartup;
    //JmgProdMultiReportFinished  jmgProdMultiReportFinished;


    while  select  sfcFeedbackStart
        order by NDXSFCid, LineNum
        where sfcFeedbackStart.NdxSFCId       == _curNdxSFCId
        &&    sfcFeedbackStart.Posted         == NoYes::No
        &&    (sfcFeedbackStart.JmgTermRegType == JmgTermRegType::JobStart
        ||     sfcFeedbackStart.JmgTermRegType == JmgTermRegType::BrkFlowStart)
        &&    sfcFeedbackStart.Deactivated    == NoYes::No
    {
        ttsbegin;
        isWorkerJobCreated = false;

        select  firstonly sfcFeedbackStop
        where sfcFeedbackStop.NdxSFCId       == _curNdxSFCId
        &&    sfcFeedbackStop.Posted         == NoYes::No
        &&    (sfcFeedbackStop.JmgTermRegType == JmgTermRegType::JobStop
        ||    sfcFeedbackStop.JmgTermRegType  == JmgTermRegType::BrkFlowStop)
        &&    sfcFeedbackStop.JmgJobId       == sfcFeedbackStart.JmgJobId
        //&&    sfcFeedbackStop.RefRecJobStart == sfcFeedbackStart.RecId
        &&    sfcFeedbackStop.Deactivated    == NoYes::No;

        if (sfcFeedbackStop.RecId)
        {
            //Todo - check is this code is still needed
            /*if (!JmgIpcActivity::findJobId(sfcFeedbackStop.JmgJobId).RecId)
            {
                if (!JmgJobBundleProdFeedbackForm::validateFeedbackQuantity(sfcFeedbackStop.ProdReportedGood, sfcFeedbackStop.JmgJobId, false, true))
                {
                    throw error("@NDX:NXAQtyCheckFailed");
                }
            }*/

            jmgTermRegJobStart.clear();
            jmgTermRegJobStart.JobId        = sfcFeedbackStart.JmgJobId;
            jmgTermRegJobStart.ResNo        = sfcFeedbackStart.WrkCtrId;
            jmgTermRegJobStart.ProfileDate  = sfcFeedbackStart.JmgDate;
            jmgTermRegJobStart.Worker       = sfcFeedbackStart.Worker;
            jmgTermRegJobStart.RegType      = sfcFeedbackStart.JmgTermRegType;
            //jmgTermRegJobStart.JobIdAbs     = sfcFeedbackStart.JmgJobId;
            jmgTermRegJobStart.RegDateTime  = sfcFeedbackStart.JmgDateTime;
            //jmgTermRegJobStart.JobPilote    = kcs_SFCFeedbackJobStart.KCS_JobPilote;
            jmgTermRegJobStart.StartItems   = sfcFeedbackStart.ProdQtyStUp;
            jmgTermRegJobStart.CostCategory = sfcFeedbackStart.CostCategory;

            jmgTermRegJobStart.AVANdxSFCId            = sfcFeedbackStart.NdxSFCId;
            jmgTermRegJobStart.AVASFCFeedbackRefRecId = sfcFeedbackStart.RecId;
            jmgTermRegJobStart.insert();



            // Ende Job
            jmgTermRegJobStop.clear();
            jmgTermRegJobStop.JobId        = sfcFeedbackStop.JmgJobId;
            jmgTermRegJobStop.ResNo        = sfcFeedbackStop.WrkCtrId;
            jmgTermRegJobStop.ProfileDate  = sfcFeedbackStop.JmgDate;
            jmgTermRegJobStop.Worker       = sfcFeedbackStart.Worker;
            jmgTermRegJobStop.RegType      = sfcFeedbackStop.JmgTermRegType;
            //jmgTermRegJobStop.JobIdAbs     = sfcFeedbackStop.JmgJobId;
            jmgTermRegJobStop.RegDateTime  = sfcFeedbackStop.JmgDateTime;
            //jmgTermRegJobStop.JobPilote    = sfcFeedbackStop.KCS_JobPilote;
            jmgTermRegJobStop.StartItems   = sfcFeedbackStop.ProdQtyStUp;
            jmgTermRegJobStop.CostCategory = sfcFeedbackStop.CostCategory;
            jmgTermRegJobStop.AVANdxSFCId  = sfcFeedbackStop.NdxSFCId;
            jmgTermRegJobStop.AVASFCFeedbackRefRecId = sfcFeedbackStop.RecId;

            if (sfcFeedbackStop.ProdReportedError != 0  && sfcFeedbackStart.JmgTermRegType == JmgTermRegType::JobStart)
            {
                jmgTmpErrorSpecification.clear();
                jmgTmpErrorSpecification.QtyError = sfcFeedbackStop.ProdReportedError;
                jmgTmpErrorSpecification.ErrorCause = ProdErrorCause::None;
                jmgTmpErrorSpecification.insert();
                jmgTermRegJobStop.ErrorSpecification = JmgErrorSpecificationForm::encodeErrorSpecification(jmgTmpErrorSpecification);
            }

            jmgTermRegJobStop.insert();

            isWorkerJobCreated = true;
        }

        if (!isWorkerJobCreated)
        {
            throw error(strfmt("@NDX:NXANDXBDSisNotCompleted", _curNdxSFCId));

        }



        jmgTermRegJobStart.selectForUpdate(true);
        jmgTermRegJobStart.reread();
        jmgTermRegJobStart.MatchRecIdStartStop = jmgTermRegJobStop.RecId;
        jmgTermRegJobStart.update();

        jmgTermRegJobStop.selectForUpdate(true);
        jmgTermRegJobStop.reread();
        jmgTermRegJobStop.MatchRecIdStartStop  = jmgTermRegJobStart.RecId;
        jmgTermRegJobStop.Update();

        jmgTermRegStartRecId = jmgTermRegJobStart.RecId;
        jmgTermRegEndRecId   = jmgTermRegJobStop.RecId;

        select firstOnly forupdate jmgStampJournalTrans
                    where jmgStampJournalTrans.JobId             == jmgTermRegJobStart.JobId
                    &&    jmgStampJournalTrans.TermRegStartRecID == jmgTermRegStartRecId
                    &&    jmgStampJournalTrans.TermRegStopRecID  == jmgTermRegEndRecId;



        jmgStampJournalTrans.Seconds    = jmgStampJournalTrans.StopTime - jmgStampJournalTrans.StartTime;

        if (sfcFeedbackStart.JmgTermRegType == JmgTermRegType::JobStart)
        {

            jmgStampJournalTrans.QtyGood    += sfcFeedbackStop.ProdReportedGood;

            if (prodParameters::find().AVABDEFinish)
            {
                jmgStampJournalTrans.QtyError   += sfcFeedbackStop.ProdReportedError;
                jmgStampJournalTrans.SysQtyError -= sfcFeedbackStop.ProdReportedError;
            }

            jmgStampJournalTrans.SysQtyGood  -= sfcFeedbackStop.ProdReportedGood;
        }

        jmgStampJournalTrans.doUpdate();

        if (sfcFeedbackStart.JmgTermRegType == JmgTermRegType::JobStart)
        {
            JmgTermJob      jmgTermJob = JmgTermJob::construct(jmgTermRegJobStop.JobId);

            JmgRegistrationParameters  jmgRegistrationParameters = JmgRegistrationParameters::constructJmgStampTransMap(jmgStampJournalTrans);
            jmgRegistrationParameters.goodQuantity(sfcFeedbackStart.ProdReportedGood);
            jmgRegistrationParameters.errorSpecification(JmgErrorSpecificationForm::encodeErrorSpecification(jmgTmpErrorSpecification));
            jmgPostStandardSystem   = JmgPostStandardSystem::construct();
            jmgPostStandardSystem.parmWorker(jmgTermRegJobStop.Worker);
            jmgPostStandardSystem.addJob(jmgTermJob, JmgRegistrationParameters::constructJmgStampTransMap(jmgStampJournalTrans),jmgStampJournalTrans);
            jmgPostStandardSystem.postTime();
        }

        /*  if (sfcFeedbackStart.TransactionType != AVASFCTransactionType::Interruption01)  //Todo
        {
            select firstOnly jmgStampJournalTrans
                where jmgStampJournalTrans.JobId             == jmgTermRegJobStart.JobId
                &&    jmgStampJournalTrans.TermRegStartRecID == jmgTermRegStartRecId
                &&    jmgStampJournalTrans.TermRegStopRecID  == jmgTermRegEndRecId;

            if (!jmgStampJournalTrans)
            {
                throw error("@NDX:NXAJmgStampNotFound");
            }
            else
            {
                jmgStampJournalTrans.QtyGood    += sfcFeedbackStop.ProdReportedGood;

                if (prodParameters::find().AVABDEFinish)
                {
                    jmgStampJournalTrans.QtyError   += sfcFeedbackStop.ProdReportedError;
                    jmgStampJournalTrans.SysQtyError -= sfcFeedbackStop.ProdReportedError;
                }
                jmgStampJournalTrans.SysQtyGood  -= sfcFeedbackStop.ProdReportedGood;
                ttsbegin;
                jmgStampJournalTrans.selectForUpdate(true);
                jmgStampJournalTrans.update();
                ttscommit;

                jmgPostStandardSystem = JmgPostStandardSystem::constructJmgStampJournalTrans(jmgStampJournalTrans);

                if (jmgStampJournalTrans.QtyStartup != jmgStampJournalTrans.SysQtyStartup)
                {
                    jmgProdMultiStartUp = jmgPostStandardSystem.createProductionStartUpJournal();
                    if (jmgProdMultiStartUp)
                    {
                        jmgProdMultiStartUp.runOperation();
                    }

                }

                if (jmgStampJournalTrans.QtyGood || jmgStampJournalTrans.ErrorSpecification || jmgStampJournalTrans.QtyError)
                {
                    jmgPostStandardSystem.postQty(jmgStampJournalTrans);
                }

                if (jmgStampJournalTrans.QtyGood || jmgStampJournalTrans.ErrorSpecification || jmgStampJournalTrans.QtyError)
                {
                    jmgProdMultiReportFinished = jmgPostStandardSystem.createReportFinishedJournal();
                    if (jmgProdMultiReportFinished)
                    {
                        jmgProdMultiReportFinished.runOperation();
                    }
                }

                if ((jmgProdMultiStartUp && jmgProdMultiStartUp.parmUserCanceled())  ||
                    (jmgProdMultiReportFinished && jmgProdMultiReportFinished.parmUserCanceled()))
                {
                    throw error("@SYS18447");
                }
            }
        }*/
        ttscommit;
    }
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_transactionType">_transactionType</param>
/// <returns>JmgJobId</returns>
